<script setup lang="ts">
const {t}=useI18n(),route=useRoute(),router=useRouter(),warehouses=useWarehouseStore(),{bizErrorMessage}=useBizError()
const data=ref<any>(null),exporting=ref(false),loading=ref(false),error=ref(''),keyword=ref(String(route.query.keyword||''))
const warehouseId=computed(()=>warehouses.currentWarehouse?.id||null)
const reportZone=computed(()=>data.value?.timezone||warehouses.currentWarehouse?.timezone||'UTC')
const { $dayjs }=useNuxtApp()
const start=computed(()=>String(route.query.start_time||'')|| (data.value?.start_time?$dayjs(data.value.start_time,'YYYY-MM-DD',reportZone.value):''))
// The API serializes the last included instant (exclusive boundary minus 1 microsecond).
const end=computed(()=>String(route.query.end_time||'')|| (data.value?.end_time?$dayjs(data.value.end_time,'YYYY-MM-DD',reportZone.value):''))
const go=(patch:Record<string,any>,keepPage=false)=>{const query:Record<string,any>={...route.query,...patch};if(!keepPage)delete query.page;for(const key of Object.keys(query))if(query[key]==null||query[key]==='')delete query[key];router.push({query})}
const download=async()=>{
 if(exporting.value||loading.value||!data.value)return
 exporting.value=true;error.value=''
 try{
  const filters:Record<string,unknown>={...route.query,warehouse_id:warehouseId.value}
  const params=new URLSearchParams(Object.entries(filters).filter(([key,value])=>!['page','per_page'].includes(key)&&value!=null&&value!=='').map(([key,value])=>[key,String(value)]))
  await downloadFile('/api/warehouse/stock-ledger/summary/export?'+params,{headers:warehouseHeaders(warehouseId.value)},'stock-summary.csv')
 }catch(e){error.value=bizErrorMessage(e as HttpRequestError)}finally{exporting.value=false}
}
const expanded=ref(new Set<string>())
const children=ref<Record<string,{items:any[];page:number;total:number;loading:boolean;error:string}>>({})
const groupKey=(row:any)=>JSON.stringify([row.warehouse_id,row.group_dimension,row.group_value??null])
let generation=0
const loadChildren=async(row:any,append=false)=>{
 const key=groupKey(row),seq=generation,previous=children.value[key]
 if(previous?.loading)return
 const nextPage=append?(previous?.page||0)+1:1
 const state={items:append?previous?.items||[]:[],page:append?previous?.page||0:0,total:previous?.total||0,loading:true,error:''}
 children.value[key]=state
 const groupFilter=row.group_value==null?{[dimension.value+'_missing']:1}:{[dimension.value]:row.group_value}
 const result=await httpRequest<any>('/api/warehouse/stock-ledger/summary',{params:{...route.query,...groupFilter,start_time:data.value?.start_time,end_time:data.value?.end_time,group_by:'goods',warehouse_id:row.warehouse_id,page:nextPage,per_page:20},headers:warehouseHeaders(row.warehouse_id),onError:e=>{if(seq===generation)state.error=bizErrorMessage(e)}})
 if(seq!==generation)return
 children.value[key]={...state,items:result?[...state.items,...result.items]:state.items,page:result?nextPage:state.page,total:result?.total??state.total,loading:false}
}
const toggle=(row:any)=>{const key=groupKey(row);if(expanded.value.has(key))expanded.value.delete(key);else{expanded.value.add(key);if(!children.value[key])loadChildren(row)}}
const visibleRows=computed(()=>(data.value?.items||[]).flatMap((row:any)=>{
 if(!row.group_dimension)return[row]
 const key=groupKey(row),state=children.value[key]
 if(!expanded.value.has(key))return[row]
 return [row,...(state?.items||[]).map(child=>({...child,_child:true,_parent:key})),...(state&&(state.loading||state.error||state.items.length<state.total)?[{_more:true,_parent:key,_group:row,_state:state}]:[])]
}))
const expandAll=()=>{for(const row of data.value?.items||[]){if(row.group_dimension&&!expanded.value.has(groupKey(row)))toggle(row)}}

const load=async()=>{const seq=++generation;expanded.value=new Set();children.value={};loading.value=true;error.value='';data.value=null;const result=await httpRequest<any>('/api/warehouse/stock-ledger/summary',{params:{...route.query,warehouse_id:warehouseId.value,per_page:50},headers:warehouseHeaders(warehouseId.value),onError:e=>{if(seq===generation)error.value=bizErrorMessage(e)}});if(seq===generation){data.value=result;loading.value=false}}
const dimension=computed(()=>String(route.query.group_by||'goods'))
const inMovements=computed(()=>[...new Set(['sort_in','adjust_gain',...Object.keys(data.value?.totals?.inbound_by_movement||{})])])
const outMovements=computed(()=>[...new Set(['ship','adjust_loss',...Object.keys(data.value?.totals?.outbound_by_movement||{})])])
const columns=computed(()=>[
 {key:'goods',label:dimension.value==='goods'?t('nav.goods'):t('stock-report.'+dimension.value),wrap:true,width:'300px'},
 {key:'warehouse',label:t('nav.warehouse')},
 {key:'opening',label:t('stock-report.opening'),type:'qty' as const,strong:true,keepZero:true},
 ...inMovements.value.map(movement=>({key:'in:'+movement,label:t('ledger.movements.'+movement),type:'qty' as const,value:(row:any)=>row._more?null:row.inbound_by_movement?.[movement]||0})),
 {key:'inbound',label:t('stock-report.inbound'),type:'qty' as const,strong:true,keepZero:true},
 ...outMovements.value.map(movement=>({key:'out:'+movement,label:t('ledger.movements.'+movement),type:'qty' as const,value:(row:any)=>row._more?null:row.outbound_by_movement?.[movement]||0})),
 {key:'outbound',label:t('stock-report.outbound'),type:'qty' as const,strong:true,keepZero:true},
 {key:'closing',label:t('stock-report.closing'),type:'qty' as const,strong:true,keepZero:true}
])
const pageTotals=computed(()=>Object.fromEntries(['opening','inbound','outbound','closing'].map(key=>[key,(data.value?.items||[]).reduce((sum:number,row:any)=>sum+Number(row[key]||0),0)])))
const summaryKeys=['opening','inbound','outbound','closing']
const scopeLabel=computed(()=>warehouses.warehouses.find(row=>row.id===warehouseId.value)?.name||t('common.all-warehouse'))
const ledgerLink=(movement?:string)=>({path:'/inventory/ledger',query:{...Object.fromEntries(Object.entries(route.query).filter(([key])=>!['page','per_page','group_by'].includes(key))),warehouse_id:warehouseId.value||undefined,start_time:data.value?.start_time||route.query.start_time||undefined,end_time:data.value?.end_time||route.query.end_time||undefined,...(movement?{movement_types:movement}:{})}})
const rowKey=(row:any)=>row._more?'more:'+row._parent:row.group_dimension?'group:'+groupKey(row):(row._parent||'')+':'+row.warehouse_id+':'+row.goods_id
watch(()=>route.query,()=>{keyword.value=String(route.query.keyword||'');load()});watch(warehouseId,()=>{if(route.query.page)go({});else load()});onMounted(async()=>{await warehouses.fetchWarehouses();load()});onBeforeUnmount(()=>generation++)
useHead({title:()=>t('stock-report.title')})
</script>
<template><div class="w-stock-report w-scope"><header class="report-heading"><div><h1>{{t('stock-report.title')}}</h1><p>{{t('stock-report.hint')}}</p></div><WButton icon="download" :loading="exporting" :disabled="loading||!data" @click="download">{{t('goods.ui.export')}}</WButton></header><form class="filters" @submit.prevent="go({keyword:keyword.trim()})"><StockReportPeriod v-if="start&&end" :start="start" :end="end" :timezone="reportZone" @change="value=>go(value)"/><StockMetadataFilter v-for="field in (['category','brand'] as const)" :key="field" :dimension="field" :warehouse-id="warehouseId" :filters="route.query" @change="value=>go(value)"/><WInput v-model="keyword" class="keyword-filter" type="search" :aria-label="t('common.search')" :placeholder="t('ledger.search')"><template #prefix><WIcon name="search" :size="16"/></template></WInput><WButton type="submit" :loading="loading">{{t('common.search')}}</WButton></form><WAlert v-if="error" tone="block" :title="error"/><section v-if="data?.totals" class="warehouse-totals" :aria-label="t('stock-report.scope-total')"><header><h2>{{t('stock-report.scope-total')}} <span>{{scopeLabel}}</span><WHelp :text="t('ledger.overview-help')" /></h2><NuxtLink :to="ledgerLink()">{{t('stock-report.period-ledger')}} →</NuxtLink></header><div class="equation"><template v-for="(key,index) in summaryKeys" :key="key"><span v-if="index" class="operator" aria-hidden="true">{{['','+','−','='][index]}}</span><div class="sum-block"><span>{{t('stock-report.'+key)}}</span><strong :class="{closing:key==='closing'}">{{Number(data.totals[key]).toLocaleString()}}</strong><div v-if="key==='inbound'||key==='outbound'" class="breakdown"><NuxtLink class="w-summary-detail" v-for="(quantity,movement) in data.totals[key+'_by_movement']" :key="movement" :to="ledgerLink(String(movement))"><span>{{t('ledger.movements.'+movement)}}</span><b>{{Number(quantity).toLocaleString()}}</b></NuxtLink></div><div v-else class="breakdown"><NuxtLink class="w-summary-detail" v-for="stockType in data.stock_types" :key="stockType" :to="{...ledgerLink(),query:{...ledgerLink().query,stock_types:stockType}}"><span>{{t('ledger.types.'+stockType)}}</span><b>{{Number(data.totals[key+'_by_stock_type']?.[stockType]||0).toLocaleString()}}</b></NuxtLink></div></div></template></div></section><WCard flush><div v-if="data" class="period">{{$dayjs(data.start_time,'YYYY-MM-DD HH:mm',reportZone)}} — {{$dayjs(data.end_time,'YYYY-MM-DD HH:mm',reportZone)}}</div><div class="dimension-bar"><span>{{t('stock-report.dimension')}}</span><WSegmented :model-value="dimension" :label="t('stock-report.dimension')" size="sm" :options="['goods','category','brand'].map(value=>({value,label:value==='goods'?t('nav.goods'):t('stock-report.'+value)}))" @update:model-value="value=>go({group_by:value})" /><template v-if="dimension==='category'||dimension==='brand'"><WButton variant="text" size="sm" @click="expandAll">{{t('stock-report.expand-all')}}</WButton><WButton variant="text" size="sm" @click="expanded.clear()">{{t('stock-report.collapse-all')}}</WButton></template></div><WTable :rows="visibleRows" :columns="columns" :row-key="rowKey"  :loading="loading" inset><template #header><tr><th rowspan="2" scope="col">{{columns[0]?.label}}</th><th rowspan="2" scope="col">{{t('nav.warehouse')}}</th><th rowspan="2" scope="col" class="number-column group-edge">{{t('stock-report.opening')}}</th><th :colspan="inMovements.length+1" scope="colgroup" class="direction-heading group-edge">{{t('stock-report.inbound')}}</th><th :colspan="outMovements.length+1" scope="colgroup" class="direction-heading group-edge">{{t('stock-report.outbound')}}</th><th rowspan="2" scope="col" class="number-column group-edge">{{t('stock-report.closing')}}</th></tr><tr><th v-for="(movement,index) in inMovements" :key="'in:'+movement" scope="col" class="number-column" :class="{'group-edge':index===0}">{{t('ledger.movements.'+movement)}}</th><th scope="col" class="number-column">{{t('stock-report.subtotal')}}</th><th v-for="(movement,index) in outMovements" :key="'out:'+movement" scope="col" class="number-column" :class="{'group-edge':index===0}">{{t('ledger.movements.'+movement)}}</th><th scope="col" class="number-column">{{t('stock-report.subtotal')}}</th></tr></template><template #cell-goods="{row}"><template v-if="row._more"><span v-if="row._state.loading">{{t('common.status.loading')}}</span><template v-else><small v-if="row._state.error" role="alert">{{row._state.error}}</small><WButton variant="text" size="sm" @click="loadChildren(row._group,true)">{{t('stock-report.load-more')}}</WButton></template></template><button v-else-if="row.group_dimension" type="button" class="group-toggle" :aria-expanded="expanded.has(groupKey(row))" @click="toggle(row)"><WIcon :name="expanded.has(groupKey(row))?'chevron-down':'chevron-right'" :size="14"/><strong>{{row.group_value||t('stock-report.unassigned')}}</strong><span>{{row.goods_count}}</span></button><div v-else :class="{'child-goods':row._child}"><NuxtLink class="w-report-goods" :to="'/goods/detail/'+row.goods_id">{{row.goods?.name}}</NuxtLink><small>{{row.goods?.code}}</small></div></template><template #cell-warehouse="{row}">{{row._more?'':warehouses.warehouses.find(item=>item.id===row.warehouse_id)?.name||row.warehouse_id}}</template><template #cell-inbound="{row}"><span class="positive">{{row.inbound}}</span></template><template #cell-outbound="{row}"><span>{{row.outbound}}</span></template></WTable><div v-if="data?.items.length" class="totals"><strong>{{t('stock-report.total')}}</strong><span v-for="key in ['opening','inbound','outbound','closing']" :key="key">{{t('stock-report.'+key)}} <b>{{pageTotals[key]}}</b></span></div><footer><WPagination :page="Number(route.query.page)||1" :page-size="50" :total="data?.total" show-total @update:page="value=>go({page:value},true)"/></footer></WCard></div></template>
<style scoped>
.w-stock-report{display:flex;flex-direction:column;gap:16px}h1{margin:0;font-size:24px;line-height:32px;font-weight:600}header p{margin:8px 0 0;font-size:13px;line-height:20px;color:var(--w-text-3)}.filters{display:flex;flex-wrap:wrap;align-items:center;gap:8px}.keyword-filter{width:260px;max-width:100%}.period{padding:12px 20px;border-bottom:1px solid var(--w-line);font-size:12px;line-height:18px;color:var(--w-text-3)}.w-stock-report :deep(.w-table){min-width:900px}.w-stock-report :deep(th){height:auto;padding-top:10px;padding-bottom:8px;line-height:16px}.w-stock-report :deep(td){padding-top:12px;padding-bottom:12px}.w-report-goods{color:var(--w-text-1);font-size:14px;font-weight:500;text-decoration:none}small{display:block;font-size:12px;line-height:18px;color:var(--w-text-3)}.positive{color:var(--w-text-1)}.totals{display:flex;justify-content:flex-end;gap:24px;flex-wrap:wrap;padding:12px 20px;border-top:1px solid var(--w-border);font-size:13px;line-height:20px;background:var(--w-surface-2)}.totals>strong{margin-right:auto}.totals b{margin-left:8px}footer{padding:12px 20px;border-top:1px solid var(--w-line)}@media(max-width:600px){.filters>.w-field{flex-basis:100%;min-width:0}.totals{gap:12px}}
.warehouse-totals{padding:16px 24px 20px;border:1px solid var(--w-border);border-radius:10px;background:var(--w-surface);display:flex;flex-direction:column;gap:16px}.warehouse-totals header{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:8px}.warehouse-totals h2{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:0;font-size:16px;line-height:24px;font-weight:600}.warehouse-totals h2>span{font-size:13px;line-height:20px;font-weight:400;color:var(--w-text-2)}.warehouse-totals header>a{font-size:13px;line-height:20px;font-weight:500;text-decoration:none}.equation{display:grid;grid-template-columns:minmax(0,1fr) 40px minmax(0,1fr) 40px minmax(0,1fr) 40px minmax(0,1fr);align-items:start}.operator{padding-top:22px;font-size:20px;line-height:28px;text-align:center;color:var(--w-text-3)}.sum-block{display:flex;flex-direction:column;gap:2px;min-width:0}.sum-block>span{font-size:12px;line-height:18px;font-weight:500;color:var(--w-text-2)}.sum-block>strong{font-size:28px;line-height:36px;font-weight:600}.sum-block>strong.closing{font-size:32px;line-height:40px}.breakdown{margin-top:8px;display:flex;flex-direction:column}.breakdown a{display:flex;justify-content:space-between;gap:12px;padding:4px 0;border-top:1px solid var(--w-line);font-size:13px;line-height:20px;color:var(--w-text-2);text-decoration:none}.breakdown b{font-weight:500;color:var(--w-text-1)}@media(max-width:650px){.equation{grid-template-columns:minmax(0,1fr) 20px minmax(0,1fr);gap:12px}.operator:nth-child(4){display:none}.sum-block>strong,.sum-block>strong.closing{font-size:24px;line-height:32px}}
.dimension-bar{display:flex;flex-wrap:wrap;align-items:center;gap:8px 12px;padding:12px 20px;border-bottom:1px solid var(--w-line);font-size:13px;line-height:20px;color:var(--w-text-2)}.dimension-bar :deep(.w-segmented){margin-right:auto}.group-toggle{display:inline-flex;align-items:center;gap:8px;border:0;padding:0;background:transparent;font:inherit;color:var(--w-text-1);cursor:pointer}.group-toggle strong{font-weight:600}.group-toggle>span{font-size:12px;color:var(--w-text-3)}.child-goods{padding-left:22px}
.w-stock-report :deep(th.number-column){text-align:right}.w-stock-report :deep(th.direction-heading){text-align:center;border-bottom:0;padding-bottom:2px}.w-stock-report :deep(th[rowspan]){vertical-align:bottom}.w-stock-report :deep(th.group-edge){border-left:1px solid var(--w-line)}.w-stock-report :deep(thead tr:nth-child(2) th){padding-top:2px}.w-stock-report :deep(.w-table){min-width:1100px}
.w-stock-report :deep(thead th){padding:10px 8px 8px;font-size:12px;line-height:16px;font-weight:500;color:var(--w-text-3);background:var(--w-surface);border-bottom:1px solid var(--w-border);white-space:nowrap;text-align:left}.w-stock-report :deep(thead tr:first-child th:first-child){padding-left:20px}.w-stock-report :deep(thead tr:first-child th:last-child){padding-right:20px;font-weight:600;color:var(--w-text-2)}.w-stock-report :deep(thead th.number-column){text-align:right}.w-stock-report :deep(thead th.direction-heading){text-align:center;border-bottom:0;padding-bottom:2px}.w-stock-report :deep(thead tr:nth-child(2) th){padding-top:2px}
.report-heading{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px}
</style>
